<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?php $editId=(int)session()->getFlashdata('edit_category_id'); ?><?= view('partials/breadcrumbs',['title'=>'Equipment Categories','subtitle'=>'Maintain reusable categories for barangay assets.']) ?><div class="grid-2 uneven"><section class="panel"><div class="panel-head"><div><h2>Categories</h2><p><?= count($rows) ?> configured</p></div></div><div class="table-wrap" role="region" aria-label="Equipment categories table" tabindex="0"><table><thead><tr><th>Name</th><th>Status</th><th>Description</th><th class="actions-head">Actions</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><b><?= esc($row['name']) ?></b></td><td><?= view('partials/status_badge',['status'=>$row['status']]) ?></td><td><?= esc($row['description']?:'—') ?></td><td class="actions"><button class="btn small ghost" type="button" data-dialog-open="category-<?= (int)$row['id'] ?>">Edit</button><form method="post" action="<?= site_url('equipment-categories/'.$row['id'].'/status') ?>" data-confirm="<?= esc(($row['status']==='active'?'Deactivate ':'Activate ').$row['name'].' category?'.($row['status']==='active'?' It will no longer be available for new or edited equipment records.':''), 'attr') ?>"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $row['status']==='active'?'inactive':'active' ?>"><button class="btn small" type="submit"><?= $row['status']==='active'?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach; ?><?php if(empty($rows)): ?><tr><td colspan="4"><div class="empty">No equipment categories configured.</div></td></tr><?php endif; ?></tbody></table></div></section><?php foreach($rows as $row): ?><?php $editing=$editId===(int)$row['id']; ?><dialog class="form-dialog" id="category-<?= (int)$row['id'] ?>" <?= $editing?'data-dialog-auto-open':'' ?>><div class="dialog-head"><h2>Edit Category</h2><button type="button" data-dialog-close aria-label="Close"><?= ui_icon('x') ?></button></div><form method="post" action="<?= site_url('equipment-categories/'.$row['id']) ?>" class="stack-form"><?= csrf_field() ?><label>Name<input name="name" value="<?= esc($editing?old('name',$row['name']):$row['name']) ?>" required<?= $editing?form_invalid('name'):'' ?>><?= $editing?form_error('name'):'' ?></label><label>Description<textarea name="description" rows="4"<?= $editing?form_invalid('description'):'' ?>><?= esc($editing?old('description',$row['description']??''):$row['description']??'') ?></textarea><?= $editing?form_error('description'):'' ?></label><input type="hidden" name="status" value="<?= esc($row['status']) ?>"><div class="form-actions"><button class="btn" type="button" data-dialog-close>Cancel</button><button class="btn primary" type="submit">Save Changes</button></div></form></dialog><?php endforeach; ?><aside class="panel action-panel"><h2>Add Category</h2><form method="post" action="<?= site_url('equipment-categories') ?>" class="stack-form"><?= csrf_field() ?><label>Name<input name="name" value="<?= esc($editId?'' : old('name')) ?>" required<?= !$editId?form_invalid('name'):'' ?>><?= !$editId?form_error('name'):'' ?></label><label>Description<textarea name="description" rows="4"<?= !$editId?form_invalid('description'):'' ?>><?= esc($editId?'':old('description')) ?></textarea><?= !$editId?form_error('description'):'' ?></label><input type="hidden" name="status" value="active"><button class="btn primary wide" type="submit">Save Category</button></form></aside></div><?= $this->endSection() ?>
